import request from '@/utils/request'
import axios from 'axios'
const baseURL = 'https://threeserver.cdutcm.edu.cn'

const token = "111"
export function post(url, data) {
  const headers = {
    "X-Access-Token": token,
    "Content-Type": "multipart/form-data",
  }
  return axios({
    url: baseURL + url,
    method: 'post',
    headers,
    data
  })
}

