// AI分析
export function DSAnalysis(result) {
  return request({
    url: 'https://api.siliconflow.cn/v1/chat/completions',
    method: 'post',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer sk-zubkifhmbdjttrtvrtczjvrxcvxbfzyntnyzruzyeuyygbcv'
    },
    data: {
      "model": "deepseek-ai/deepseek-vl2",
      "messages": [
          {
              "role": "user",
              "content": [{
                  "type": "image_url",
                  "image_url": {
                      "url": result.imgUrl
                  }
              }]
          },
          {
              "role": "user",
              "content": `${result.patAge && `年龄${result.patAge}岁`}${result.patSex && result.patSex === '1' ? '男士' : '女士'}，请分析舌头里的状态，分别指出舌色（淡红舌、淡白舌、红舌、绛舌、青紫舌），舌形（老舌、嫩舌、胖大舌、肿胀舌、瘦薄舌、点刺舌、裂纹舌、齿痕舌、），苔质（薄、厚苔、润、燥苔、腻、腐苔、剥（落）苔、偏、全苔），苔色（白苔、黄苔、灰黑苔），津液（润、滑、燥）。按中文键名的json格式返回`
          }
      ],
      "stream": false,
      "max_tokens": 512,
      "stop": [
          "null"
      ],
      "temperature": 0.7,
      "top_p": 0.7,
      "top_k": 50,
      "frequency_penalty": 0.5,
      "n": 1,
      "response_format": {
          "type": "text"
      }
    }
  })
}