<template>
  <div class="page">
    <el-form
      :inline="true"
      :model="form"
      class="demo-form-inline">
      <el-form-item>
        <el-input v-model="form.name" placeholder="姓名"></el-input>
      </el-form-item>
      <el-form-item>
        <el-select v-model="form.auditStatus" placeholder="请选择" clearable>
          <el-option label="待审核" :value="0"></el-option>
          <el-option label="已审核" :value="1"></el-option>
        </el-select>
      </el-form-item>
      <el-form-item>
        <el-button type="primary" @click="getDiagnosisResult">查询</el-button>
      </el-form-item>
    </el-form>
    <el-table
      :data="showTableData"
      border
      style="width: 100%">
      <el-table-column
        prop="name"
        label="姓名"
        align="center"
        width="100">
      </el-table-column>
      <el-table-column
        prop="imgurl"
        label="图片"
        align="center"
        width="150">
        <template slot-scope="{row}">
          <!-- <img class="img" :src="row.imgUrl" alt=""> -->
          <el-image 
            class="img"
            :src="row.imgUrl" 
            :preview-src-list="[row.imgUrl]">
          </el-image>
        </template>
      </el-table-column>
      <el-table-column
        prop="createTime"
        label="上传时间"
        align="center"
        width="140">
      </el-table-column>
      <el-table-column
        prop="createTime"
        label="结果来源"
        align="center"
        width="140">
        <template>
          <div class="contrast-cell">
            <div>
              AI分析
            </div>
            <div>
              {{hsopUser.userName}}
            </div>
          </div>
        </template>
      </el-table-column>
      <el-table-column
        prop="imgFlag"
        align="center"
        label="图片质量"
        width="80">
        <template slot-scope="{row}">
          <el-tag
            v-if="row.imgFlag !== undefined"
            :type="row.imgFlag === 0 ? 'success' : 'danger'"
            disable-transitions>{{row.imgFlag === 0? '合格' : '不合格'}}</el-tag>
        </template>
      </el-table-column>
      <el-table-column
        prop="tongueColour"
        label="舌色">
        <template slot-scope="{row}">
          <div class="contrast-cell">
            <div>
              {{row.tongueColour}}
            </div>
            <div v-if="!row.imgFlag" :style="{color: row.tongueColour === row.tongueColour1 ? '':'red'}">
              {{row.tongueColour1}}
            </div>
            <div v-else>
              /
            </div>
          </div>
        </template>
      </el-table-column>
      <el-table-column
        prop="tongueShapes"
        label="舌形">
        <template slot-scope="{row}">
          <div class="contrast-cell">
            <div>
              {{row.tongueShapes}}
            </div>
            <div v-if="!row.imgFlag" :style="{color: row.tongueShapes === row.tongueShapes1 ? '':'red'}">
              {{row.tongueShapes1}}
            </div>
            <div v-else>
              /
            </div>
          </div>
        </template>
      </el-table-column>
      <el-table-column
        prop="tongueFurqualitys"
        label="苔质">
        <template slot-scope="{row}">
          <div class="contrast-cell">
            <div>
              {{row.tongueFurqualitys}}
            </div>
            <div v-if="!row.imgFlag" :style="{color: row.tongueFurqualitys === row.tongueFurqualitys1 ? '':'red'}">
              {{row.tongueFurqualitys1}}
            </div>
            <div v-else>
              /
            </div>
          </div>
        </template>
      </el-table-column>
      <el-table-column
        prop="tonguefurColour"
        label="苔色">
        <template slot-scope="{row}">
          <div class="contrast-cell">
            <div>
              {{row.tonguefurColour}}
            </div>
            <div v-if="!row.imgFlag" :style="{color: row.tonguefurColour === row.tonguefurColour1 ? '':'red'}">
              {{row.tonguefurColour1}}
            </div>
            <div v-else>
              /
            </div>
          </div>
        </template>
      </el-table-column>
      <el-table-column
        prop="bodyFluid"
        label="津液">
        <template slot-scope="{row}">
          <div class="contrast-cell">
            <div>
              {{row.bodyFluid}}
            </div>
            <div v-if="!row.imgFlag" :style="{color: row.bodyFluid === row.bodyFluid1 ? '':'red'}">
              {{row.bodyFluid1}}
            </div>
            <div v-else>
              /
            </div>
          </div>
        </template>
      </el-table-column>
      <el-table-column
        prop="address"
        align="center"
        label="操作">
        <template slot-scope="{row}">
          <el-button type="primary" @click="show(row)">查看</el-button>
        </template>
      </el-table-column>
    </el-table>
  </div>
</template>

<script>
import { getDiagnosisResult } from '@/service/shezhen';
import { mapGetters } from 'vuex'

export default {
  name: 'ShezhenAdminResult',

  data() {
    return {
      form: {},
      auditStatus: null,
      tableData: []
    };
  },
  computed: {
    ...mapGetters(["hsopUser"]),
    showTableData() {
      console.log(123123123)
      // return this.tableData.filter(item => {
      //   return item.imgFlag !== null
      // })

      if (this.auditStatus === 0) {
        return this.tableData.filter(item => {
          return item.imgFlag === null
        })
      } else if (this.auditStatus === 1) {
        return this.tableData.filter(item => {
          return item.imgFlag !== null
        })
      } else {
        return this.tableData
      }

    }
  },

  mounted() {
    this.getDiagnosisResult()
  },

  methods: {
    getDiagnosisResult() {
      getDiagnosisResult(this.form).then(res => {
        this.auditStatus = this.form.auditStatus
        this.tableData = res;
      });
    },
    show(row) {
      this.$router.push({
        name: 'detail',
        query: {
          id: row.id,
          result: JSON.stringify({
            tongueColour: row.tongueColour,
            tongueShapes: row.tongueShapes,
            tongueFurqualitys: row.tongueFurqualitys,
            tonguefurColour: row.tonguefurColour,
            bodyFluid: row.bodyFluid
          })
        },
        params: {
          title: row.name
        }
      });
    }
  },
};
</script>

<style lang="less" scoped>
.page {
  background-color: #FFF;
  padding: 20px;
}
.img {
  width: 100px;
  height: 100px;;
}
/deep/.cell {
  padding: 0;
}
.contrast-cell {
  display: flex;
  flex-direction: column;
  >div {
    height: 50px;
    line-height: 50px;
    text-align: center;
    &:nth-child(1) {
      border-bottom: 1px solid #EBEEF5;
    }
  }
}
</style>